// Compile-time Factorial using template specialization (TMP)
template<int N>
struct Factorial {
    static constexpr int value = N * Factorial<N - 1>::value;
};

// Base Case
template<>
struct Factorial<0> {
    static constexpr int value = 1;
};

// Calculation performed entirely during compilation
void usage() {
    static_assert(Factorial<4>::value == 24);
    constexpr int result = Factorial<5>::value; // result == 120
}
